sys_script_include.script:
var ApolloDoctorAvailability = Class.create();
ApolloDoctorAvailability.prototype = {
    initialize: function() {
        this.SCOPE = 'x_2223823_apollo_0';
        this.TABLE_DOCTOR = 'x_2223823_apollo_0_doctor';
        this.TABLE_DOCTOR_REQUEST = 'x_2223823_apollo_0_doctor_request';
        this.TABLE_APPOINTMENT = 'x_2223823_apollo_0_appointment';
        this.TABLE_HOSPITAL = 'x_2223823_apollo_0_hospital';
        this.INACTIVE_STATUSES = ['6', '7', '8', '9', 'completed', 'cancelled', 'rescheduled', 'no_show', 'no show'];
    },

    /**
     * Main validation method called on Appointment Before Insert/Update.
     * Evaluates Doctor Status, Mode Enabled (OPD vs Video), Hospital/Cover, Leave, and Working Schedule.
     * 
     * @param {GlideRecord} current - The appointment record being inserted or updated
     * @returns {Object} { valid: Boolean, message: String, availableSlotsMsg: String }
     */
    validateDoctor: function(current) {
        try {
            var status = current.getValue('status');
            if (status && this.INACTIVE_STATUSES.indexOf(String(status).toLowerCase()) !== -1) {
                return { valid: true }; // Inactive transitions release slots, allow immediately
            }

            var doctorId = current.getValue('doctor');
            var hospitalId = current.getValue('hospital');
            var startTimeStr = current.getValue('start_time');
            var endTimeStr = current.getValue('end_time');
            var modeVal = current.getValue('mode'); // '1' = In-Person, '2' = Video

            // If start_time or doctor is missing, allow other mandatory field validations to catch it
            if (!doctorId || !startTimeStr) {
                return { valid: true };
            }

            var isVideo = (modeVal === '2' || String(modeVal).toLowerCase() === 'video');
            var modeLabel = isVideo ? 'Video' : 'In-Person OPD';

            var startGdt = new GlideDateTime(startTimeStr);
            var dateStr = startTimeStr.split(' ')[0]; // YYYY-MM-DD
            var timeOnlyStart = startTimeStr.split(' ')[1] || '00:00:00';

            // Load Doctor Record
            var docGr = new GlideRecord(this.TABLE_DOCTOR);
            if (!docGr.get(doctorId)) {
                return { valid: false, message: 'Selected doctor record was not found.' };
            }
            var doctorName = docGr.getDisplayValue('user') || docGr.getValue('number') || 'Doctor';

            // ---------------------------------------------------------------------
            // CHECK 1: Doctor Active Status & Mode Enabled (OPD vs Video)
            // ---------------------------------------------------------------------
            var docStatus = String(docGr.getValue('status') || '1');
            if (docStatus !== '1') {
                return {
                    valid: false,
                    message: 'Doctor ' + doctorName + ' is currently inactive and cannot accept appointments.'
                };
            }

            if (isVideo) {
                var videoEnabled = docGr.getValue('video_enabled');
                if (videoEnabled !== true && videoEnabled !== '1' && videoEnabled !== 'true') {
                    return {
                        valid: false,
                        message: 'Doctor ' + doctorName + ' is currently not available for Video consultations (Video consultation is disabled on doctor profile).'
                    };
                }
            } else {
                var opdEnabled = docGr.getValue('opd_enabled');
                if (opdEnabled !== true && opdEnabled !== '1' && opdEnabled !== 'true') {
                    return {
                        valid: false,
                        message: 'Doctor ' + doctorName + ' is currently not available for In-Person OPD consultations (OPD is disabled on doctor profile).'
                    };
                }
            }

            // ---------------------------------------------------------------------
            // CHECK 2: Hospital & Approved Temporary Cover
            // ---------------------------------------------------------------------
            var primaryHospital = docGr.getValue('primary_hospital');
            var isAtHospital = false;
            var hospitalName = current.getDisplayValue('hospital') || 'this hospital';

            if (!hospitalId || !primaryHospital || (primaryHospital === hospitalId)) {
                isAtHospital = true;
            } else {
                // Check if doctor has an APPROVED Cover request for this hospital on this date
                var coverGr = new GlideRecord(this.TABLE_DOCTOR_REQUEST);
                coverGr.addQuery('doctor', doctorId);
                coverGr.addQuery('request_type', 'cover');
                coverGr.addQuery('status', 'approved');
                coverGr.addQuery('hospital', hospitalId);
                coverGr.addQuery('start_date', '<=', dateStr);
                coverGr.addQuery('end_date', '>=', dateStr);
                coverGr.setLimit(1);
                coverGr.query();
                if (coverGr.next()) {
                    isAtHospital = true;
                }
            }

            if (!isAtHospital) {
                var primaryHospName = docGr.getDisplayValue('primary_hospital') || 'another location';
                return {
                    valid: false,
                    message: 'Doctor ' + doctorName + ' is not scheduled at ' + hospitalName + ' on ' + dateStr + 
                             '. Doctor\'s primary hospital is ' + primaryHospName + ' (no approved cover request found for ' + hospitalName + ').'
                };
            }

            // ---------------------------------------------------------------------
            // CHECK 3: Approved Leave Check (Applies to both OPD & Video)
            // ---------------------------------------------------------------------
            var leaveGr = new GlideRecord(this.TABLE_DOCTOR_REQUEST);
            leaveGr.addQuery('doctor', doctorId);
            leaveGr.addQuery('request_type', 'leave');
            leaveGr.addQuery('status', 'approved');
            leaveGr.addQuery('start_date', '<=', dateStr);
            leaveGr.addQuery('end_date', '>=', dateStr);
            leaveGr.setLimit(1);
            leaveGr.query();

            if (leaveGr.next()) {
                var lStart = leaveGr.getValue('start_date');
                var lEnd = leaveGr.getValue('end_date');
                return {
                    valid: false,
                    message: 'Appointment cannot be booked: Doctor ' + doctorName + ' is on approved leave on ' + dateStr + 
                             ' (Leave Period: ' + lStart + ' to ' + lEnd + ').'
                };
            }

            // ---------------------------------------------------------------------
            // CHECK 4: Working Hours / Schedule Check (Video Timings vs OPD Timings)
            // ---------------------------------------------------------------------
            var scheduleId = isVideo ? (docGr.getValue('video_schedule') || docGr.getValue('opd_schedule')) : docGr.getValue('opd_schedule');
            var isWithinSchedule = false;
            var hoursText = '08:00 - 17:00 (Weekdays)';

            if (scheduleId) {
                hoursText = this._getScheduleDisplayText(scheduleId);
                try {
                    var sched = new GlideSchedule(scheduleId);
                    if (sched && sched.isValid()) {
                        isWithinSchedule = sched.isInSchedule(startGdt);
                        if (isWithinSchedule && endTimeStr) {
                            var endGdt = new GlideDateTime(endTimeStr);
                            isWithinSchedule = sched.isInSchedule(endGdt);
                        }
                    } else {
                        isWithinSchedule = this._checkHourRange(timeOnlyStart, '08:00:00', '17:00:00');
                    }
                } catch (eSched) {
                    isWithinSchedule = this._checkHourRange(timeOnlyStart, '08:00:00', '17:00:00');
                }
            } else {
                isWithinSchedule = this._checkHourRange(timeOnlyStart, '08:00:00', '17:00:00');
            }

            if (!isWithinSchedule) {
                var slotsList = this.getAvailableSlots(doctorId, hospitalId, dateStr, isVideo);
                var slotTimes = [];
                for (var i = 0; i < slotsList.length; i++) {
                    var slotTime = slotsList[i].start_time.split(' ')[1];
                    slotTimes.push(slotTime.substring(0, 5));
                }
                var slotsStr = slotTimes.length > 0 ? slotTimes.join(', ') : 'No remaining free ' + modeLabel + ' slots for today.';

                return {
                    valid: false,
                    message: 'Selected time (' + timeOnlyStart.substring(0, 5) + 
                             ') is outside Doctor ' + doctorName + '\'s ' + modeLabel + ' schedule on ' + dateStr + ' (' + hoursText + ').',
                    availableSlotsMsg: 'Available ' + modeLabel + ' slots for ' + doctorName + ' on ' + dateStr + ': ' + slotsStr
                };
            }

            return { valid: true };

        } catch (ex) {
            gs.error('[ApolloDoctorAvailability] Exception in validateDoctor: ' + ex.message);
            return {
                valid: false,
                message: 'Doctor Availability Validation error: ' + ex.message
            };
        }
    },

    /**
     * Calculates all available slots for a doctor on a given date:
     * 1. Uses video_duration or opd_duration based on mode.
     * 2. Slices the appropriate schedule (video_schedule vs opd_schedule).
     * 3. Subtracts all active booked appointments (both OPD & Video).
     */
    getAvailableSlots: function(doctorId, hospitalId, dateStr, isVideo) {
        var docGr = new GlideRecord(this.TABLE_DOCTOR);
        if (!docGr.get(doctorId)) return [];

        // Read duration dynamically based on mode
        var durationField = isVideo ? 'video_duration' : 'opd_duration';
        var duration = parseInt(docGr.getValue(durationField), 10);
        if (isNaN(duration) || duration <= 0) {
            duration = 15;
        }

        // Read schedule dynamically based on mode
        var scheduleId = isVideo 
            ? (docGr.getValue('video_schedule') || docGr.getValue('opd_schedule'))
            : docGr.getValue('opd_schedule');

        var windows = this._getScheduleWindows(scheduleId);
        if (!windows || windows.length === 0) {
            windows = [{ start: '08:00:00', end: '17:00:00' }];
        }

        // Step A: Generate all raw slots from the working windows
        var rawSlots = [];
        for (var w = 0; w < windows.length; w++) {
            var win = windows[w];
            var startMin = this._timeToMinutes(win.start);
            var endMin = this._timeToMinutes(win.end);

            var currMin = startMin;
            while (currMin + duration <= endMin) {
                var slotStart = this._minutesToTime(currMin);
                var slotEnd = this._minutesToTime(currMin + duration);

                rawSlots.push({
                    start_time: dateStr + ' ' + slotStart,
                    end_time: dateStr + ' ' + slotEnd,
                    duration_minutes: duration
                });
                currMin += duration;
            }
        }

        // Step B: Fetch ALL active booked appointments for this doctor on this date (both OPD & Video)
        var bookedAppointments = [];
        var aptGr = new GlideRecord(this.TABLE_APPOINTMENT);
        aptGr.addQuery('doctor', doctorId);
        aptGr.addEncodedQuery('statusNOT IN' + this.INACTIVE_STATUSES.join(','));
        aptGr.addQuery('start_time', '>=', dateStr + ' 00:00:00');
        aptGr.addQuery('start_time', '<=', dateStr + ' 23:59:59');
        aptGr.query();

        while (aptGr.next()) {
            bookedAppointments.push({
                start: String(aptGr.getValue('start_time')),
                end: String(aptGr.getValue('end_time'))
            });
        }

        // Step C: Filter out any slot that overlaps with an active appointment
        var availableSlots = [];
        for (var s = 0; s < rawSlots.length; s++) {
            var slot = rawSlots[s];
            var isConflict = false;

            for (var b = 0; b < bookedAppointments.length; b++) {
                var booked = bookedAppointments[b];
                if (booked.start < slot.end_time && booked.end > slot.start_time) {
                    isConflict = true;
                    break;
                }
            }

            if (!isConflict) {
                availableSlots.push(slot);
            }
        }

        return availableSlots;
    },

    _checkHourRange: function(timeStr, startLimit, endLimit) {
        var t = this._timeToMinutes(timeStr);
        var s = this._timeToMinutes(startLimit);
        var e = this._timeToMinutes(endLimit);
        return (t >= s && t < e);
    },

    _getScheduleWindows: function(scheduleId) {
        var windows = [];
        if (!scheduleId) {
            windows.push({ start: '08:00:00', end: '17:00:00' });
            return windows;
        }

        try {
            var spanGr = new GlideRecord('cmn_schedule_span');
            spanGr.addQuery('schedule', scheduleId);
            spanGr.addQuery('type', '!=', 'exclude');
            spanGr.query();

            while (spanGr.next()) {
                var sTime = spanGr.getValue('start_date_time');
                var eTime = spanGr.getValue('end_date_time');
                var parsedStart = this._parseSpanTime(sTime, '08:00:00');
                var parsedEnd = this._parseSpanTime(eTime, '17:00:00');
                windows.push({ start: parsedStart, end: parsedEnd });
                break;
            }
        } catch (e) {}

        if (windows.length === 0) {
            try {
                var schedGr = new GlideRecord('cmn_schedule');
                if (schedGr.get(scheduleId)) {
                    var schedName = (schedGr.getValue('name') || '').toLowerCase();
                    if (schedName.indexOf('8-20') !== -1) {
                        windows.push({ start: '08:00:00', end: '20:00:00' });
                    } else {
                        windows.push({ start: '08:00:00', end: '17:00:00' });
                    }
                } else {
                    windows.push({ start: '08:00:00', end: '17:00:00' });
                }
            } catch (ex) {
                windows.push({ start: '08:00:00', end: '17:00:00' });
            }
        }
        return windows;
    },

    _getScheduleDisplayText: function(scheduleId) {
        try {
            var schedGr = new GlideRecord('cmn_schedule');
            if (schedGr.get(scheduleId)) {
                var sName = schedGr.getValue('name');
                if (sName) return sName;
            }
        } catch (e) {}
        return '8-5 Weekdays';
    },

    _parseSpanTime: function(isoDateTimeStr, defaultTime) {
        if (!isoDateTimeStr) return defaultTime;
        var parts = isoDateTimeStr.split('T');
        if (parts.length > 1) {
            var t = parts[1];
            if (t.length >= 6) {
                return t.substring(0, 2) + ':' + t.substring(2, 4) + ':' + t.substring(4, 6);
            }
        }
        return defaultTime;
    },

    _timeToMinutes: function(timeStr) {
        if (!timeStr) return 0;
        var p = timeStr.split(':');
        var h = parseInt(p[0], 10) || 0;
        var m = parseInt(p[1], 10) || 0;
        return (h * 60) + m;
    },

    _minutesToTime: function(totalMinutes) {
        var h = Math.floor(totalMinutes / 60);
        var m = totalMinutes % 60;
        var hh = (h < 10 ? '0' : '') + h;
        var mm = (m < 10 ? '0' : '') + m;
        return hh + ':' + mm + ':00';
    },

    type: 'ApolloDoctorAvailability'
};
